parameters.jsCode:
const raw = $json.output?.[0]?.content?.[0]?.text ?? "";
let parsed;
try {
  parsed = JSON.parse(raw.replace(/```json|```/g, "").trim());
} catch (e) {
  return [{ json: { variant_group: $('Loop Product Groups').item.json.variant_group,
                     valid: false, fail: "unparseable", fail_reason: "AI response wasn't valid JSON — check LM Studio output." } }];
}

const rows = $('Loop Product Groups').item.json.rows;
const sourceText = rows.map(r => `${r.raw_name} ${r.material || ""} ${r.dimensions || ""} ${r.raw_notes || ""}`)
  .join(" ").toLowerCase();

const desc = (parsed.description || "").trim();
const title = (parsed.title || "").trim();
const bulletsText = (parsed.bullets || []).join(" ");
const words = desc.split(/\s+/).length;

const bannedClaims = /certified|organic|eco-friendly|handmade|guaranteed for life|clinically|patented/i;
const bannedSuperlatives = /\b(best|amazing|premium|luxurious|revolutionary|stylish|sleek|modern|elegant|chic|trendy)\b/i;

const variantValues = new Set();
if (rows.length > 1) {
  rows.forEach(r => {
    (r.variant_attrs || "").split(",").forEach(pair => {
      const val = pair.split(":")[1];
      if (val) variantValues.add(val.trim().toLowerCase());
    });
  });
}
const sharedText = `${title} ${desc}`.toLowerCase();
const leakedValue = [...variantValues].find(v => v && new RegExp(`\\b${v}\\b`, "i").test(sharedText));

const numberClaims = [...desc.matchAll(/\b(\d+)\s*(hour|hr|day|year|degree|lb|pound|oz|ounce|watt|volt)/gi)];
const sourceNumberUnitPairs = new Set(
  [...sourceText.matchAll(/\b(\d+)\s*(hour|hr|day|year|degree|lb|pound|oz|ounce|watt|volt)/gi)]
    .map(m => `${m[1]}${m[2].toLowerCase()}`)
);
const fabricatedNumber = numberClaims.find(m => !sourceNumberUnitPairs.has(`${m[1]}${m[2].toLowerCase()}`));

const internalLeakPhrases = /\b(no|not)\b.{0,15}\bspecified\b|not provided|\btbd\b|to be determined|not available yet|\bunknown\b|pending (full )?spec/i;
const leakedInternalNote = internalLeakPhrases.test(desc) || internalLeakPhrases.test(title) || internalLeakPhrases.test(bulletsText);

// Catch the model treating a SKU like a brand name (e.g. "Canvas Backpack by BACK-CNV-01").
// A SKU appearing anywhere in customer-facing text is never something a customer should see.
const skuList = rows.map(r => r.sku).filter(Boolean);
const leakedSku = skuList.find(sku => sharedText.includes(sku.toLowerCase()) || bulletsText.toLowerCase().includes(sku.toLowerCase()));

const checks = {
  hasTitle:          title.length > 5 && title.length <= 70,
  hasDescription:    words >= 15 && words <= 140,
  bulletCount:       Array.isArray(parsed.bullets) && parsed.bullets.length >= 3 && parsed.bullets.length <= 6,
  seoMetaLength:      (parsed.seo_meta || "").length > 0 && parsed.seo_meta.length <= 155,
  noUnsourcedClaim:   !bannedClaims.test(desc) || bannedClaims.test(sourceText),
  noUnsourcedClaimTitle: !bannedClaims.test(title) || bannedClaims.test(sourceText),
  noBareSuperlative:  !bannedSuperlatives.test(desc) && !bannedSuperlatives.test(title),
  variantsMatch:      (parsed.variants || []).length === rows.length,
  noVariantLeak:      !leakedValue,
  noFabricatedNumber: !fabricatedNumber,
  noInternalLeak:     !leakedInternalNote,
  noSkuLeak:          !leakedSku
};

const failed = Object.entries(checks).filter(([,v]) => !v).map(([k]) => k);

const reasons = {
  hasTitle: "Title is missing or too long.",
  hasDescription: "Description is the wrong length.",
  bulletCount: "Wrong number of bullet points.",
  seoMetaLength: "SEO meta text is missing or too long.",
  noUnsourcedClaim: 'AI added a claim not backed by your product data (like "eco-friendly" or "certified") in the description.',
  noUnsourcedClaimTitle: 'AI added a claim not backed by your product data (like "eco-friendly" or "certified") in the title.',
  noBareSuperlative: 'Title or description uses a vague marketing word (like "stylish" or "premium") without support.',
  variantsMatch: "AI didn't write copy for every variant in the group.",
  noVariantLeak: `Shared title/description mentions a variant-specific detail ("${leakedValue}") that doesn't apply to every variant in the group.`,
  noFabricatedNumber: `AI invented a specific number/spec ("${fabricatedNumber ? fabricatedNumber[0] : ''}") not present in your source data.`,
  noInternalLeak: "Customer-facing copy mentions missing/incomplete data (an internal note leaked into the listing) — this needs to read naturally without it.",
  noSkuLeak: `AI treated the SKU ("${leakedSku}") like a brand name and included it in customer-facing text.`
};
const fail_reason = failed.length === 0 ? "" : failed.map(k => reasons[k] || k).join(" ");

return [{ json: {
  variant_group: $('Loop Product Groups').item.json.variant_group,
  rows,
  parsed,
  valid: failed.length === 0,
  fail: failed.join(","),
  fail_reason
}}];

const text = $json.message?.text || "";
const approveMatch = text.match(/^approve\s+(\S+)/i);
const rejectMatch = text.match(/^reject\s+(\S+)\s*(.*)/i);

if (approveMatch) {
  return [{ json: { action: "approve", variant_group: approveMatch[1] } }];
}
if (rejectMatch) {
  return [{ json: { action: "reject", variant_group: rejectMatch[1], reason: rejectMatch[2] } }];
}
return [{ json: { action: "ignore" } }];
